// The reductions figure's data model, free of the DOM: the measured sweep
// (measured.ts, generated by analyze_reductions_bench.py), the derived units,
// and the dispatch-cost model that predicts a threaded call from the pooled
// measurement plus a fixed cost per call.

import { CLOCK_GHZ, DISPATCH_US, NS_PER_ELEM, SIZES } from "./measured";

export { CLOCK_GHZ, DISPATCH_US, NS_PER_ELEM, SIZES };
export const KiB = 1024;
export const MiB = 1024 * KiB;
export const GiB = 1024 * MiB;

export type Group = "scalar" | "vector" | "threads";
export interface Variant {
  id: string;
  label: string;
  group: Group;
}

export const VARIANTS: readonly Variant[] = [
  { id: "naive_scalar", label: "naive, scalar", group: "scalar" },
  { id: "ilp_scalar", label: "ilp, scalar", group: "scalar" },
  { id: "naive", label: "naive", group: "vector" },
  { id: "ilp", label: "ilp", group: "vector" },
  { id: "simd", label: "simd", group: "vector" },
  { id: "ilp_simd", label: "ilp_simd", group: "vector" },
  { id: "opt", label: "opt (clang)", group: "vector" },
  { id: "ilp_avx512", label: "ilp_avx512", group: "vector" },
  { id: "thread_spawn", label: "thread, spawn", group: "threads" },
  { id: "thread_pool", label: "thread, pool", group: "threads" },
  { id: "all_spawn", label: "all, spawn", group: "threads" },
  { id: "all_pool", label: "all, pool", group: "threads" },
];
export const SINGLE: readonly string[] = VARIANTS.filter((v) => v.group !== "threads").map((v) => v.id);

/** Cache capacities of the test VM, per core except L3. */
export const LEVELS = [
  { name: "L1d", bytes: 48 * KiB },
  { name: "L2", bytes: 2 * MiB },
  { name: "L3", bytes: 260 * MiB },
] as const;

export type PresetId = "chain" | "compilers" | "threads" | "all";
export const PRESETS: Record<PresetId, { label: string; shown: readonly string[]; model: boolean }> = {
  chain: { label: "Dependency chains", shown: ["naive_scalar", "ilp_scalar", "naive", "ilp_simd", "ilp_avx512"], model: false },
  compilers: { label: "Compilers", shown: ["naive", "ilp", "simd", "ilp_simd", "opt"], model: false },
  threads: { label: "Thread start-up", shown: ["ilp_avx512", "all_spawn", "all_pool"], model: true },
  all: { label: "All variants", shown: VARIANTS.map((v) => v.id), model: false },
};
export const PRESET_IDS = Object.keys(PRESETS) as PresetId[];

export const ns = (id: string, i: number): number => NS_PER_ELEM[id][i][0];
export const nsMin = (id: string, i: number): number => NS_PER_ELEM[id][i][1];
export const nsMax = (id: string, i: number): number => NS_PER_ELEM[id][i][2];
/** GB/s from ns per 8-byte element. */
export const gbs = (nsPerElem: number): number => 8 / nsPerElem;
export const elemsPerCycle = (nsPerElem: number): number => 1 / (nsPerElem * CLOCK_GHZ);

/** The fastest single-thread variant at each measured size. */
export function bestSingle(i: number): { id: string; ns: number } {
  let best = { id: SINGLE[0], ns: ns(SINGLE[0], i) };
  for (const id of SINGLE) if (ns(id, i) < best.ns) best = { id, ns: ns(id, i) };
  return best;
}
export const bestSingleSeries = (): number[] => SIZES.map((_, i) => bestSingle(i).ns);
export const series = (id: string): number[] => SIZES.map((_, i) => ns(id, i));

/**
 * ns per element at any size between the measured ones, interpolating
 * ln(ns per element) linearly in log2(bytes).
 */
export function interp(values: readonly number[], sizes: readonly number[], bytes: number): number {
  const x = Math.log2(bytes);
  if (x <= Math.log2(sizes[0])) return values[0];
  for (let i = 1; i < sizes.length; i++) {
    const x1 = Math.log2(sizes[i]);
    if (x <= x1) {
      const x0 = Math.log2(sizes[i - 1]);
      const t = (x - x0) / (x1 - x0);
      return Math.exp(Math.log(values[i - 1]) * (1 - t) + Math.log(values[i]) * t);
    }
  }
  return values[values.length - 1];
}

/**
 * Predicted ns per element of a threaded call that costs dUs of dispatch:
 * the pooled measurement, minus the pool's own dispatch cost (hotUs, workers
 * spinning), plus dUs, spread over the bytes/8 elements.
 */
export function predicted(poolNs: number, bytes: number, dUs: number, hotUs: number = DISPATCH_US.poolHot): number {
  return poolNs + ((dUs - hotUs) * 1000) / (bytes / 8);
}

/**
 * Smallest array size at which the predicted threaded call is faster than
 * the single-thread series, or null if it never is within the measured
 * range. Scans in steps of 1/32 octave, then bisects.
 */
export function breakEven(
  single: readonly number[],
  pool: readonly number[],
  sizes: readonly number[],
  dUs: number,
  hotUs: number = DISPATCH_US.poolHot,
): number | null {
  const f = (x: number) => {
    const b = 2 ** x;
    return predicted(interp(pool, sizes, b), b, dUs, hotUs) - interp(single, sizes, b);
  };
  const lo = Math.log2(sizes[0]);
  const hi = Math.log2(sizes[sizes.length - 1]);
  if (f(lo) < 0) return sizes[0];
  for (let x = lo; x < hi; x += 1 / 32) {
    const x1 = Math.min(x + 1 / 32, hi);
    if (f(x1) < 0) {
      let a = x;
      let b = x1;
      for (let k = 0; k < 50; k++) {
        const m = (a + b) / 2;
        if (f(m) < 0) b = m;
        else a = m;
      }
      return 2 ** b;
    }
  }
  return null;
}

/** Slider position (0..SLIDER_MAX) to dispatch cost in microseconds, log scale. */
export const SLIDER_MAX = 200;
export const D_LO = DISPATCH_US.poolHot;
export const D_HI = 1000;
export const sliderToUs = (p: number): number => D_LO * (D_HI / D_LO) ** (p / SLIDER_MAX);
export const usToSlider = (us: number): number =>
  Math.round((Math.log(Math.min(Math.max(us, D_LO), D_HI) / D_LO) / Math.log(D_HI / D_LO)) * SLIDER_MAX);

export function sizeLabel(bytes: number): string {
  const fmt = (v: number) => (v >= 100 ? v.toFixed(0) : v >= 10 ? v.toFixed(0) : +v.toFixed(1) + "");
  if (bytes >= GiB) return `${fmt(bytes / GiB)} GiB`;
  if (bytes >= MiB) return `${fmt(bytes / MiB)} MiB`;
  return `${fmt(bytes / KiB)} KiB`;
}
export function usLabel(us: number): string {
  if (us >= 100) return `${us.toFixed(0)} µs`;
  if (us >= 10) return `${us.toFixed(0)} µs`;
  return `${us.toFixed(2)} µs`;
}
